import sys
import logging
import os
import tempfile
from functools import wraps
from taf.selenium.core.common import PagePart


class Debug(PagePart):
    def __init__(self, alias=None, debug_dir=None):
        super(Debug, self).__init__(alias)
        if debug_dir is None:
            self._debug_dir = tempfile.mkdtemp(prefix="taf_selenium_debug")
        else:
            self._debug_dir = debug_dir
        if not os.path.exists(self._debug_dir):
            os.makedirs(self._debug_dir)


def catch_interface_exception(func):
    """
    Method to catch exception and save screenshot if function raises an error
    """

    @wraps(func)
    def interface_func(*args, **kwargs):
        if "coam" not in kwargs:
            kwargs['coam'] = 'default'
        try:
            outcome = func(*args, **kwargs)
        except Exception:
            instance = args[0]
            Debug(instance.store.get(kwargs['coam'])._driver, instance._debug_dir).save_screenshot(
                '{}'.format(func.__name__), screenshot_dir=instance._debug_dir)
            logging.info("Current used python version is: %s", sys.version.split(' ')[0])
            raise
        return outcome

    return interface_func
